/* Map an ai.js faction key back to its art entry. */
function facArt(k){
  const raw=String(k||'').trim().toLowerCase();
  if(FACART[raw]) return FACART[raw];
  for(const id in FACART) if(FACART[id].key===raw) return FACART[id];
  /* Full doctrinal names appear in saves, dispatches and imported scenarios.
     Machine Ascendancy must be checked before the generic word Ascendancy or
     it is incorrectly painted as the Red Legion. These aliases intentionally
     collapse lore names onto the four playable identities; they never create
     a fifth faction. */
  const key=raw.includes('machine ascendancy')||raw.includes('syndicate')||raw.includes('coalition')?'syndicate':
    raw.includes('infestation')||raw.includes('umbral brood')||raw.includes('brood')||raw.includes('swarm')?'horde':
    raw.includes('terran frontline')||raw.includes('nova federation')||raw.includes('frontline')||raw.includes('federation')?'nova':
    raw.includes('red ascendancy')||raw.includes('bloodward')||raw.includes('legion')||raw==='ascendancy'?'ascendancy':null;
  if(key&&FACART[key]) return FACART[key];
  return null;
}
/* A crest at a given pixel size. Picks the nearest source above the requested
   size so the GPU never upscales, and degrades to the faction emoji if the art
   is missing — which is what happens in the single-file dev bundle, where there
   is no assets folder beside the HTML. */
function facIcon(k,size,cls){
  const A=facArt(k);
  const s=size||36;
  if(!A){
    const F=(typeof FACTIONS!=='undefined'&&FACTIONS[k])||null;
    return '<span style="font-size:'+Math.round(s*0.8)+'px">'+(F?F.em:'◈')+'</span>';
  }
  const src=s<=48?48:(s<=96?96:256);
  const F=(typeof FACTIONS!=='undefined'&&FACTIONS[A.key])||null;
  return '<img class="facIc'+(cls?' '+cls:'')+'" alt="'+A.nm+'" width="'+s+'" height="'+s+'"'
    +' src="./assets/factions/'+A.id+'_icon_'+src+'.png"'
    +' onerror="this.replaceWith(Object.assign(document.createElement(\'span\'),'
    +'{textContent:\''+(F?F.em:'◈')+'\',style:\'font-size:'+Math.round(s*0.8)+'px\'}))">';
}
/* Canvas consumers (deployment map and tactical minimap) use the exact same
   crest files as DOM cards. Images are cached once; callers keep their normal
   geometric fallback until decode completes, so a slow asset never blanks a
   strategic marker. */
const facIconCanvasCache={};
function facIconCanvas(k,onready){
  const A=facArt(k);if(!A)return null;
  let I=facIconCanvasCache[A.id];
  if(!I){I=new Image();I.decoding='async';I.src='./assets/factions/'+A.id+'_icon_48.png';facIconCanvasCache[A.id]=I;}
  if(onready&&!I.complete&&!I._mfReady){I._mfReady=true;I.addEventListener('load',onready,{once:true});}
  return I.complete&&I.naturalWidth?I:null;
}
function facPortrait(id,size){
  const s=size||192;
  return '<img class="facPort" alt="" width="'+s+'" height="'+s+'" loading="lazy"'
    +' src="./assets/factions/'+id+'_'+(s<=192?192:512)+'.jpg"'
    +' onerror="this.style.display=\'none\'">';
}

/* ---- codex cards ---------------------------------------------------------- */
/* THE CODEX MUST NOT CONTRADICT THE BUILD MENU.
   FACART.units was hand-written prose that named its own units and was linked
   to TYPES by nothing at all, so the moment src/factext.js gave each faction a
   word for every chassis the two surfaces disagreed out loud: the Dossier said
   RHINO and the Dominion build menu said Iron Ram, for the same slot, in the
   same session. A codex entry is now a ROSTER SLOT — the TYPES index — and its
   name is resolved through the same seam every card, tooltip and production
   entry reads. The longer codex prose stays; only the name stopped being a
   second, drifting copy.
   An entry whose first field is a STRING is a unit with no roster slot of its
   own: the faction air transports are registered at runtime by src/airlift.js
   and their build card reads TYPES[].name directly, so they keep the authored
   lore name rather than gaining a third spelling. */
function facUnitName(id,u){
  if(typeof u[0]!=='number') return String(u[0]);
  const A=FACART[id], kit=(A&&A.key)||'nova';
  const n=(typeof factionUnitName==='function')?factionUnitName(u[0],kit):'';
  return (n||((typeof TYPES!=='undefined'&&TYPES[u[0]]&&TYPES[u[0]].name)||'')).toUpperCase();
}
function facCard(id){
  const A=FACART[id];
  return '<section class="facCard" style="--fc:'+A.col+';--fc2:'+A.col2+'">'
    +'<div class="facHd">'
      +'<div class="facCrest">'+facIcon(id,54)+'</div>'
      +'<div class="facNm"><b>'+A.nm+'</b><span>'+A.motto+'</span></div>'
      +(A.side==='player'?'<div class="facTag">YOUR BANNER</div>':'')
    +'</div>'
    +'<div class="facBody">'
      +'<div class="facPortWrap">'+facPortrait(id,192)+'</div>'
      +'<div class="facText">'+A.lore
        +'<div class="facCdr">COMMANDER<b>'+A.cdr+'</b>'
        +'<i>&ldquo;'+A.quote+'&rdquo;</i></div>'
      +'</div>'
    +'</div>'
    +'<div class="facUnits">'
      +A.units.map(u=>'<div class="facUnit"><b>'+facUnitName(id,u)+'</b><span>'+u[1]+'</span><i>'+u[2]+'</i></div>').join('')
    +'</div>'
    +'<div class="facDoctrine"><div class="facStrong"><b>STRONG AT</b>'+A.strong+'</div>'
      +'<div class="facWeak"><b>WEAK AGAINST</b>'+A.weak+'</div></div>'
    +'<div class="facEndgoal"><span>CAMPAIGN ENDGOAL</span><b>'+A.arc+'</b><p>'+A.endgoal+'</p></div>'
    +'<div class="facBonus"><span class="facBonusNm">'+A.bonusNm+'</span>'+A.bonus+'</div>'
  +'</section>';
}
function renderCodex(){
  const el=document.getElementById('codexList');
  if(!el) return;
  /* The codex used to be the hidden second tab of a two-tab Dossier, so the
     shell shipped it with an inline display:none that only the (now deleted)
     tab handler ever cleared. Devices that already took an OTA still carry that
     markup — an OTA replaces scripts, never index.html — so clear it here, or
     those players keep landing on an empty Dossier forever. */
  el.style.removeProperty('display');
  el.innerHTML=Object.keys(FACART).map(facCard).join('');
}

