  const roster=COMMANDER_ROSTERS[fac]||COMMANDER_ROSTERS.nova;
  let C=roster.find(c=>c.id===playerCommanderId&&!c.aiOnly);
  if(!C){C=roster.find(c=>!c.aiOnly)||COMMANDER_ROSTERS.nova[0];playerCommanderId=C.id;}
